os.makedirs("/content/t2v", exist_ok=True)
os.makedirs("/content/data", exist_ok=True)
os.chdir("/content")
for path, src in {**FILES, **DATA}.items():
    with open(path, "w") as f:
        f.write(src)
desc = json.loads(DATA["data/descriptions_imagenet.json"])
nb = json.loads(DATA["data/neighbors_imagenet.json"])
print(f"wrote {len(FILES)} code files; TokenFactory outputs: descriptions for {len(desc)} classes, "
      f"visual analogies for {len(nb['holdout'])} new + {len(nb['val'])} validation classes")

# ---------------------------------------------------------------- setup
sh("nvidia-smi --query-gpu=name,memory.total --format=csv")
sh("pip -q install transformers huggingface_hub pyarrow")
if not os.path.isdir("/content/drive/MyDrive"):
    from google.colab import drive
    drive.mount("/content/drive")
os.makedirs(OUT, exist_ok=True)
ZOO, CKPT, py = f"{OUT}/zoo", f"{OUT}/{VERSION}.pt", sys.executable
RECIPE = f"--epochs {ZOO_EPOCHS} --finetune {FINETUNE} --soup {SOUP} --amp --fp16"

# ImageNet-1k 32x32 from Hugging Face (~650 MB), cached once so the parallel processes below share it
sh(f"{py} -c \"from t2v.data import ImageNet32; d = ImageNet32('data', 'cpu', {PER_CLASS}); "
   f"print(len(d.train_y), 'train /', len(d.test_y), 'test images')\"")

# ---------------------------------------------------------------- 1. generic ResNet-20 on the 900 seen classes
if not os.path.exists(f"{ZOO}/generic.pt"):
    sh(f"{py} -m t2v.zoo generic --dataset imagenet32 --per_class {PER_CLASS} --split_file data/imagenet_split.json "
       f"--arch resnet20 --out {ZOO} --epochs {GENERIC_EPOCHS} --lr 0.1 --bs 256 --amp")

# ---------------------------------------------------------------- 2. model zoo: 1000 tasks of 2-10 seen classes
parallel([f"{py} -m t2v.zoo pmodels --out {ZOO} --split train --n {N_TRAIN} --min_k 2 {RECIPE} "
          f"--shard {s} --num_shards 4 --save_every 25" for s in range(4)],
         [f"{OUT}/zoo_train_{s}.log" for s in range(4)], "model zoo")

# ---------------------------------------------------------------- 3. test tasks (10 classes each), same recipe
EVAL = {"eval_seen": f"--n_train_ref {N_TRAIN}", "eval_unseen": "", "eval_novel": "", "eval_novel_hard": ""}
parallel([f"{py} -m t2v.zoo pmodels --out {ZOO} --split {s} --n {N_EVAL} {RECIPE} {x} --save_every 25"
          for s, x in EVAL.items()], [f"{OUT}/zoo_{s}.log" for s in EVAL], "test tasks")
sh(f"{py} -m t2v.zoo analyze --out {ZOO} --soup {SOUP}")

# ---------------------------------------------------------------- 4. the generator
if not os.path.exists(f"{CKPT}.done"):
    sh(f"{py} -m t2v.train_gen --zoo {ZOO} --out {CKPT} --token_size 1024 --d_model 512 --denoiser mlp "
       f"--mlp_hidden 1024 --joint_layers 4 --bs 32 --tokens_per_step 4096 --steps {GEN_STEPS} --warmup 300 "
       f"--pred x0 --norm element --head_weight 10 --semantic_prior --descriptions data/descriptions_imagenet.json "
       f"--neighbors data/neighbors_imagenet.json --prompt_ensemble --emb_noise 0.02 --ema 0.999 --cosine --fp16 "
       f"--log_every 500 --save_every 1000")
    open(f"{CKPT}.done", "w").write("ok")

# ---------------------------------------------------------------- 5. evaluation (100 tasks per split)
SPLITS = ["eval_seen", "eval_unseen", "eval_novel", "eval_novel_hard"]
NEW = "eval_unseen,eval_novel,eval_novel_hard"
RUNS = {  # tag: (splits, flags)
    "t2v_1k": (",".join(SPLITS), "--gate auto --prior auto"),
    "llm": (NEW, "--gate auto --prior llm"),
    "clip": (NEW, "--gate auto --prior clip"),
    "ridge": (NEW, "--gate auto --prior ridge"),
    "nogate": (NEW, "--prior ridge"),
}
for tag, (splits, flags) in RUNS.items():
    out = f"{OUT}/eval_{tag}.json"
    if not os.path.exists(out):
        sh(f"{py} -m t2v.evaluate --ckpt {CKPT} --zoo {ZOO} --splits {splits} --max_tasks {N_EVAL} --samples 1 "
           f"--steps 5 --fp16 --body_noise 0 {flags} --out {out}")
sh(f"{py} -m t2v.diagnose --ckpt {CKPT} --zoo {ZOO} --tasks 50 --steps 5 --fp16 --body_noise 0 "
   f"--splits eval_seen,eval_novel,eval_novel_hard --out {OUT}/diagnose_{VERSION}.json")
sh(f"{py} -m t2v.generate --ckpt {CKPT} --prompt 'great white shark, banjo, cello, koala, ostrich, pizza' "
   f"--out {OUT}/demo")

# ---------------------------------------------------------------- summary
R = {t: json.load(open(f"{OUT}/eval_{t}.json")) for t in RUNS}
import torch
ck_info = torch.load(CKPT, map_location="cpu", weights_only=False)
g = lambda t, s, k="generated_mean": R[t][s]["summary"][k] if s in R[t] else float("nan")
names = {"eval_seen": "seen classes", "eval_unseen": "half new", "eval_novel": "all new",
         "eval_novel_hard": "all new, hard"}
print("\n" + "=" * 86)
print(f"T2V-1K: {R['t2v_1k']['num_params']:,} ResNet-20 parameters generated from text in "
      f"{g('t2v_1k', 'eval_seen', 'seconds_per_model'):.3f} s; ImageNet-1k 32x32, 100 tasks per split, 10 classes each")
print(f"{'':34s}" + "".join(f"{names[s]:>13s}" for s in SPLITS))
row = lambda label, f: print(f"{label:34s}" + "".join(f"{f(s):13.3f}" for s in SPLITS))
row("T2V-1K (final)", lambda s: g("t2v_1k", s))
row("  prior: TokenFactory analogies", lambda s: g("llm", s))
row("  prior: CLIP neighbours", lambda s: g("clip", s))
row("  prior: ridge only", lambda s: g("ridge", s))
row("  no known-class gate", lambda s: g("nogate", s))
